import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.B8bWmLDN.js";const m=JSON.parse('{"title":"Examples","description":"Eighteen worked examples live in the repository, under [`examples/`](https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples). Each directory...","frontmatter":{"title":"Examples","description":"Eighteen worked examples live in the repository, under [`examples/`](https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples). Each directory..."},"headers":[],"relativePath":"guide/examples.md","filePath":"guide/examples.md","lastUpdated":1787675851000}'),i={name:"guide/examples.md"};function n(o,e,p,d,h,l){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>Eighteen worked examples live in the repository, under <a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples" target="_blank" rel="noreferrer"><code>examples/</code></a>. Each directory holds the TypeSpec source and the <code>tspconfig.yaml</code> it was compiled with. Seventeen of them also hold the <code>asyncapi.yaml</code> the emitter wrote from that source. The Protobuf example holds the <code>.proto</code> files the official emitter wrote. Two examples hold the <code>.avsc</code> files <code>tsp-avro</code> wrote. One of those two writes no document.</p><p>The output is committed, so you can read an input and its output side by side without running anything. Every one of the seventeen documents passes the official AsyncAPI parser.</p><h2 id="the-examples" tabindex="-1">The examples <a class="header-anchor" href="#the-examples" aria-label="Permalink to &quot;The examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/01-hello-world" target="_blank" rel="noreferrer">Hello world</a></td><td>The smallest document the emitter can produce. <code>@service</code> and <code>@info</code>, and nothing else.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/02-payload-schemas" target="_blank" rel="noreferrer">Payload schemas</a></td><td>The shapes of the schema layer: models, scalars, enums, arrays, records, and the constraints on them.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/03-schema-composition" target="_blank" rel="noreferrer">Schema composition</a></td><td>Four ways to build one schema out of others, plus the <code>@jsonSchemaExtension</code> escape hatch.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/04-message-metadata" target="_blank" rel="noreferrer">Message metadata</a></td><td>Everything that sits around a payload: headers, correlation ids, examples, tags and links.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/05-channels-and-parameters" target="_blank" rel="noreferrer">Channels and parameters</a></td><td>Channel ids, templated addresses, and the parameters an address declares.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/06-servers-and-security" target="_blank" rel="noreferrer">Servers and security</a></td><td>Servers, server variables, and the security schemes a server offers.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/07-request-and-reply" target="_blank" rel="noreferrer">Request and reply</a></td><td>Three operations, and the two shapes an AsyncAPI reply can take.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/08-kafka-user-signup" target="_blank" rel="noreferrer">Kafka user signup</a></td><td>One realistic Kafka contract, with all four Kafka bindings on one document. It also carries an Avro payload and a Protobuf payload.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/09-protocol-bindings" target="_blank" rel="noreferrer">MQTT bindings</a></td><td>The three MQTT decorators, and the one kind of name the generic <code>@binding</code> still carries.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/10-streetlights-kafka" target="_blank" rel="noreferrer">Streetlights</a></td><td>The canonical AsyncAPI example, written in TypeSpec.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/11-multi-protocol" target="_blank" rel="noreferrer">Multiple protocols</a></td><td>One application over Kafka, WebSocket and SQS, from one payload model.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/12-http-callbacks" target="_blank" rel="noreferrer">HTTP callbacks</a></td><td>The HTTP bindings on a webhook, including the <code>statusCode</code> of a reply.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/13-enterprise-brokers" target="_blank" rel="noreferrer">Enterprise brokers</a></td><td>AMQP, JMS, IBM MQ and Anypoint MQ describing one destination four ways.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/14-streaming-platforms" target="_blank" rel="noreferrer">Streaming platforms</a></td><td>NATS, Pulsar, Google Cloud Pub/Sub and Solace, and the fields each one requires.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/15-specification-extensions" target="_blank" rel="noreferrer">Specification extensions</a></td><td>The <code>x-</code> fields the specification leaves to the author, on all four objects that take one.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/16-protobuf-payloads" target="_blank" rel="noreferrer">Protobuf payloads</a></td><td>Two Protobuf packages over RabbitMQ, with the <code>.proto</code> files emitted next to the document.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/17-avro-schemas" target="_blank" rel="noreferrer">Avro schemas</a></td><td>One order domain written as Avro schema files by <code>tsp-avro</code>. No AsyncAPI document.</td></tr><tr><td><a href="https://github.com/marvin-hsu/tsp-asyncapi/tree/main/examples/18-avro-payloads" target="_blank" rel="noreferrer">Avro payloads</a></td><td>Two Avro records over Kafka, with the <code>.avsc</code> files emitted next to the document.</td></tr></tbody></table><h2 id="running-one" tabindex="-1">Running one <a class="header-anchor" href="#running-one" aria-label="Permalink to &quot;Running one&quot;">​</a></h2><p>Clone the repository and compile inside the directory you want:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/marvin-hsu/tsp-asyncapi.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsp-asyncapi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/01-hello-world</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The emitter writes <code>asyncapi.yaml</code> next to <code>main.tsp</code>, overwriting the copy in the repository. <code>git diff</code> then shows whether your build produces what was committed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Every <code>main.tsp</code> starts with <code>import &quot;../..&quot;;</code>, which points at the root of this repository. In your own project, depend on the package and write <code>import &quot;tsp-asyncapi&quot;;</code> instead.</p></div>`,10)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
